const cp = require("child_process");
// A child gets only its stdio: descriptor 9, which the program inherits
// without close-on-exec, is closed in it, on Linux as on macOS.
module.exports = function run() {
  if (process.env.TOV_TEST_FD9 === "1") {
    const out = cp.execSync("if true 2>/dev/null <&9; then echo open; else echo closed; fi", { encoding: "utf8" });
    return "descriptor 9 in the child: " + out.trim();
  }
  // (the program again, run by a shell that opens descriptor 9 first)
  const env = { ...process.env, TOV_TEST_FD9: "1" };
  return cp.execFileSync("sh", ["-c", 'exec 9</dev/null; exec "$0"', process.execPath], { env, encoding: "utf8" }).trim();
};
